10	    mountView,
11	    onRpc,
12	} from "@web/../tests/web_test_helpers";
13	
14	// Must match RELOAD_THROTTLE_INTERVAL in realtime_list_controller.js (D10).
15	const INTERVAL = 2000;
16	const NOTIFICATION_TYPE = "lyd.sale.record/created";
17	
18	class LydSaleRecord extends models.Model {
19	    _name = "lyd.sale.record";
20	
21	    date = fields.Date();
22	    amount_total = fields.Float();
23	
24	    _records = [
25	        { id: 1, date: "2026-06-01", amount_total: 100000 },
26	        { id: 2, date: "2026-06-02", amount_total: 110000 },
27	    ];
28	
29	    get_dashboard_data() {
30	        return {
31	            currency_id: false,
32	            month_total: 0,
33	            month_count: 0,
34	            filter_total: 210000,
35	            filter_count: 2,
36	        };
37	    }
38	}
39	
40	defineBusModels();
41	defineModels([LydSaleRecord]);
42	
43	describe.current.tags("desktop");
44	
45	describe("lyd_sale_record realtime list", () => {
46	    let reloadCount = 0;
47	
48	    /** Mounts the list with the module's js_class and counts the list reloads. */
49	    async function mountRealtimeList() {
50	        reloadCount = 0;
51	        onRpc("web_search_read", () => {
52	            reloadCount++;
53	            expect.step("reload");
54	        });
55	        const view = await mountView({
56	            type: "list",
57	            resModel: "lyd.sale.record",
58	            arch: `
59	                <list js_class="lyd_sale_record_realtime_list">
60	                    <field name="date"/>
61	                    <field name="amount_total"/>
62	                </list>`,
63	        });
64	        expect.verifySteps(["reload"]); // initial load
65	        return view;
66	    }
67	
68	    /** Simulates the server notification sent by ``lyd.sale.record.create``. */
69	    async function notifyCreated() {
70	        MockServer.env["bus.bus"]._sendone("broadcast", NOTIFICATION_TYPE, { count: 1 });
71	        await animationFrame();
72	    }
73	
74	    test("a single notification reloads the list immediately (leading edge)", async () => {
75	        await mountRealtimeList();
76	        await notifyCreated();
77	        await advanceTime(0);
78	        await animationFrame();
79	        expect.verifySteps(["reload"]);
80	        // nothing else is scheduled afterwards: no polling without events
81	        await advanceTime(INTERVAL * 5);
82	        await animationFrame();
83	        expect.verifySteps([]);
84	    });
85	
86	    test("a short burst reloads at most twice (leading + trailing edge)", async () => {
87	        await mountRealtimeList();
88	        await notifyCreated(); // first event -> leading reload
89	        await advanceTime(0);
90	        await animationFrame();
91	        for (let i = 0; i < 20; i++) {
92	            await notifyCreated(); // absorbed by the open window
93	        }
94	        await advanceTime(0);
95	        await animationFrame();
96	        expect.verifySteps(["reload"]);
97	        await advanceTime(INTERVAL);
98	        await animationFrame();
99	        expect.verifySteps(["reload"]); // trailing reload: the last events are not lost
100	        await advanceTime(INTERVAL * 5);
101	        await animationFrame();
102	        expect.verifySteps([]);
103	    });
104	
105	    test("a sustained stream keeps refreshing the list (no debounce starvation)", async () => {
106	        await mountRealtimeList();
107	        const initialLoads = reloadCount;
108	        // one event every 500 ms during 10 s: a debounce(2 s) would not reload until the end
109	        for (let elapsed = 0; elapsed < 10000; elapsed += 500) {
110	            await notifyCreated();
111	            await advanceTime(500);
112	            await animationFrame();
113	        }
114	        const reloads = reloadCount - initialLoads;
115	        // at most one reload per 2 s window (0, 2, 4, 6, 8, 10 s) and several during the stream
116	        expect(reloads).toBeGreaterThan(3);
117	        expect(reloads).toBeLessThan(8);
118	        expect.verifySteps(Array(reloads).fill("reload"));
119	        await advanceTime(INTERVAL * 3);
120	        await animationFrame();
121	        expect.verifySteps([]); // stream over: nothing left scheduled
122	    });
123	
124	    test("no reload after the view is destroyed (pending timer cancelled, listener removed)", async () => {
125	        const view = await mountRealtimeList();
126	        await notifyCreated(); // leading reload
127	        await advanceTime(0);
128	        await animationFrame();
129	        expect.verifySteps(["reload"]);
130	        await notifyCreated(); // schedules a trailing reload...
131	        view.__owl__.destroy(); // ...but the user leaves the screen before it fires
132	        await advanceTime(INTERVAL * 2);
133	        await animationFrame();
134	        await notifyCreated(); // event after leaving: nobody listens anymore
135	        await advanceTime(INTERVAL * 2);
136	        await animationFrame();
137	        expect.verifySteps([]);
138	    });
139	
140	    test("reload is deferred while records are selected, then applied", async () => {
141	        await mountRealtimeList();
142	        await contains(".o_data_row:first-child .o_list_record_selector input").click();
143	        await notifyCreated();
144	        await advanceTime(INTERVAL * 3);
145	        await animationFrame();
146	        expect.verifySteps([]); // the selection is not lost
147	        await contains(".o_data_row:first-child .o_list_record_selector input").click();
148	        await advanceTime(INTERVAL);
149	        await animationFrame();
150	        expect.verifySteps(["reload"]);
151	    });
152	});

